CREATE TABLE IF NOT EXISTS "account_transactions" (
	-- 거래 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 계좌 ID
	"account_id" UUID NOT NULL,
	-- 이체 ID
	"transfer_id" UUID,
	-- 카드결제 ID
	"card_payment_id" BIGINT,
	-- 거래 유형: DEPOSIT 입금 / WITHDRAW 출금 / TRANSFER 이체 / AUTO_TRANSFER 자동이체 / CARD 카드
	"transaction_type" VARCHAR(20) NOT NULL,
	-- 입출금 구분: IN 입금 / OUT 출금
	"transaction_direction" VARCHAR(3) NOT NULL,
	-- 거래 금액 (원)
	"amount" BIGINT NOT NULL,
	-- 거래 후 잔액 (원)
	"new_balance" BIGINT NOT NULL,
	-- 상대방 이름 (카드는 가맹점명)
	"counterparty_name" VARCHAR(100),
	-- 상대방 계좌번호
	"counterparty_account" VARCHAR(13),
	-- 적요
	"memo" VARCHAR(100),
	-- 거래일시
	"transaction_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "account_transactions" IS '계좌 거래내역 (거래원장)';
COMMENT ON COLUMN "account_transactions"."id" IS '거래 ID';
COMMENT ON COLUMN "account_transactions"."account_id" IS '계좌 ID';
COMMENT ON COLUMN "account_transactions"."transfer_id" IS '이체 ID';
COMMENT ON COLUMN "account_transactions"."card_payment_id" IS '카드결제 ID';
COMMENT ON COLUMN "account_transactions"."transaction_type" IS '거래 유형: DEPOSIT 입금 / WITHDRAW 출금 / TRANSFER 이체 / AUTO_TRANSFER 자동이체 / CARD 카드';
COMMENT ON COLUMN "account_transactions"."transaction_direction" IS '입출금 구분: IN 입금 / OUT 출금';
COMMENT ON COLUMN "account_transactions"."amount" IS '거래 금액 (원)';
COMMENT ON COLUMN "account_transactions"."new_balance" IS '거래 후 잔액 (원)';
COMMENT ON COLUMN "account_transactions"."counterparty_name" IS '상대방 이름 (카드는 가맹점명)';
COMMENT ON COLUMN "account_transactions"."counterparty_account" IS '상대방 계좌번호';
COMMENT ON COLUMN "account_transactions"."memo" IS '적요';
COMMENT ON COLUMN "account_transactions"."transaction_at" IS '거래일시';

CREATE INDEX "idx_account_transactions_account_at"
ON "account_transactions" ("account_id", "transaction_at");

CREATE TABLE IF NOT EXISTS "card_payments" (
	-- 카드결제 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 카드 ID
	"card_id" UUID NOT NULL,
	-- 결제 금액 (원)
	"amount" BIGINT NOT NULL,
	-- 가맹점명
	"place" VARCHAR(100),
	-- 결제 요청일시
	"request_at" TIMESTAMPTZ NOT NULL,
	-- 결제 완료일시
	"complete_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "card_payments" IS '카드 결제내역';
COMMENT ON COLUMN "card_payments"."id" IS '카드결제 ID';
COMMENT ON COLUMN "card_payments"."card_id" IS '카드 ID';
COMMENT ON COLUMN "card_payments"."amount" IS '결제 금액 (원)';
COMMENT ON COLUMN "card_payments"."place" IS '가맹점명';
COMMENT ON COLUMN "card_payments"."request_at" IS '결제 요청일시';
COMMENT ON COLUMN "card_payments"."complete_at" IS '결제 완료일시';

CREATE INDEX "idx_card_payments_card_id"
ON "card_payments" ("card_id");

CREATE TABLE IF NOT EXISTS "cards" (
	-- 카드 ID
	"id" UUID,
	-- 연결 계좌 ID
	"account_id" UUID NOT NULL,
	-- 카드번호 (암호화, 화면은 끝 4자리만)
	"card_number" VARCHAR(255) NOT NULL UNIQUE,
	-- 유효기간 (MM/YY)
	"expiry_date" VARCHAR(5) NOT NULL,
	-- 카드 브랜드: VISA / MASTER / LOCAL
	"card_network" VARCHAR(20),
	-- 1일 사용한도 (원)
	"daily_limit" BIGINT NOT NULL DEFAULT 1000000,
	-- 해외결제 허용 여부
	"overseas_enabled" BOOLEAN NOT NULL DEFAULT false,
	-- 재발급 전 카드 ID
	"reissued_from_id" UUID,
	-- 카드 상태: ACTIVE 정상 / SUSPENDED 정지 / LOST 분실 / REISSUED 재발급됨 / CANCELED 해지
	"status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
	-- 발급일시
	"created_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cards" IS '체크카드';
COMMENT ON COLUMN "cards"."id" IS '카드 ID';
COMMENT ON COLUMN "cards"."account_id" IS '연결 계좌 ID';
COMMENT ON COLUMN "cards"."card_number" IS '카드번호 (암호화, 화면은 끝 4자리만)';
COMMENT ON COLUMN "cards"."expiry_date" IS '유효기간 (MM/YY)';
COMMENT ON COLUMN "cards"."card_network" IS '카드 브랜드: VISA / MASTER / LOCAL';
COMMENT ON COLUMN "cards"."daily_limit" IS '1일 사용한도 (원)';
COMMENT ON COLUMN "cards"."overseas_enabled" IS '해외결제 허용 여부';
COMMENT ON COLUMN "cards"."reissued_from_id" IS '재발급 전 카드 ID';
COMMENT ON COLUMN "cards"."status" IS '카드 상태: ACTIVE 정상 / SUSPENDED 정지 / LOST 분실 / REISSUED 재발급됨 / CANCELED 해지';
COMMENT ON COLUMN "cards"."created_at" IS '발급일시';

CREATE TABLE IF NOT EXISTS "transfers" (
	-- 이체 ID
	"id" UUID,
	-- 중복 방지 키
	"idempotency_key" VARCHAR(100) NOT NULL UNIQUE,
	-- 출금 계좌 ID
	"from_account_id" UUID NOT NULL,
	-- 입금 계좌 ID
	"to_account_id" UUID NOT NULL,
	-- 자동이체 ID
	"auto_transfer_id" UUID,
	-- 이체 금액 (원)
	"amount" BIGINT NOT NULL,
	-- 메모
	"memo" VARCHAR(100),
	-- 처리 상태: PENDING 처리중 / SUCCESS 성공 / FAILED 실패
	"status" VARCHAR(20) NOT NULL,
	-- 실패 사유
	"fail_reason" VARCHAR(200),
	-- 요청일시
	"request_at" TIMESTAMPTZ NOT NULL,
	-- 완료일시
	"complete_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "transfers" IS '이체';
COMMENT ON COLUMN "transfers"."id" IS '이체 ID';
COMMENT ON COLUMN "transfers"."idempotency_key" IS '중복 방지 키';
COMMENT ON COLUMN "transfers"."from_account_id" IS '출금 계좌 ID';
COMMENT ON COLUMN "transfers"."to_account_id" IS '입금 계좌 ID';
COMMENT ON COLUMN "transfers"."auto_transfer_id" IS '자동이체 ID';
COMMENT ON COLUMN "transfers"."amount" IS '이체 금액 (원)';
COMMENT ON COLUMN "transfers"."memo" IS '메모';
COMMENT ON COLUMN "transfers"."status" IS '처리 상태: PENDING 처리중 / SUCCESS 성공 / FAILED 실패';
COMMENT ON COLUMN "transfers"."fail_reason" IS '실패 사유';
COMMENT ON COLUMN "transfers"."request_at" IS '요청일시';
COMMENT ON COLUMN "transfers"."complete_at" IS '완료일시';

CREATE TABLE IF NOT EXISTS "accounts" (
	-- 계좌 ID
	"id" UUID,
	-- 소유 회원 ID
	"user_id" UUID NOT NULL,
	-- 상품 ID
	"product_id" BIGINT NOT NULL,
	-- 계좌번호 (xxx-xxxx-xxxx)
	"account_num" VARCHAR(13) NOT NULL UNIQUE,
	-- 통장 비밀번호 4자리 (해시)
	"account_password" VARCHAR(255) NOT NULL,
	-- 통장 비밀번호 실패 횟수
	"password_fail_count" INT NOT NULL DEFAULT '0',
	-- 잔액 (원)
	"balance" BIGINT NOT NULL DEFAULT 0,
	-- 계좌 별칭
	"nickname" VARCHAR(50),
	-- 즐겨찾기 여부
	"is_favorite" BOOLEAN NOT NULL DEFAULT false,
	-- 1일 이체한도 (원)
	"daily_limit" BIGINT NOT NULL DEFAULT 1000000,
	-- 1달 이체한도 (원)
	"month_limit" BIGINT NOT NULL DEFAULT 5000000,
	-- 개설 목적·거래정보
	"opening_info" JSONB,
	-- 계좌 상태: ACTIVE 정상 / SUSPENDED 거래중지 / CLOSED 해지
	"status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
	-- 개설일시
	"created_at" TIMESTAMPTZ NOT NULL,
	-- 해지일시
	"closed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "accounts" IS '계좌';
COMMENT ON COLUMN "accounts"."id" IS '계좌 ID';
COMMENT ON COLUMN "accounts"."user_id" IS '소유 회원 ID';
COMMENT ON COLUMN "accounts"."product_id" IS '상품 ID';
COMMENT ON COLUMN "accounts"."account_num" IS '계좌번호 (xxx-xxxx-xxxx)';
COMMENT ON COLUMN "accounts"."account_password" IS '통장 비밀번호 4자리 (해시)';
COMMENT ON COLUMN "accounts"."password_fail_count" IS '통장 비밀번호 실패 횟수';
COMMENT ON COLUMN "accounts"."balance" IS '잔액 (원)';
COMMENT ON COLUMN "accounts"."nickname" IS '계좌 별칭';
COMMENT ON COLUMN "accounts"."is_favorite" IS '즐겨찾기 여부';
COMMENT ON COLUMN "accounts"."daily_limit" IS '1일 이체한도 (원)';
COMMENT ON COLUMN "accounts"."month_limit" IS '1달 이체한도 (원)';
COMMENT ON COLUMN "accounts"."opening_info" IS '개설 목적·거래정보';
COMMENT ON COLUMN "accounts"."status" IS '계좌 상태: ACTIVE 정상 / SUSPENDED 거래중지 / CLOSED 해지';
COMMENT ON COLUMN "accounts"."created_at" IS '개설일시';
COMMENT ON COLUMN "accounts"."closed_at" IS '해지일시';

CREATE TABLE IF NOT EXISTS "account_products" (
	-- 상품 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 상품명
	"product_name" VARCHAR(100) NOT NULL,
	-- 연 금리 (%)
	"interest_rate" NUMERIC(5,3),
	-- 상품 설명
	"description" TEXT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "account_products" IS '계좌 상품';
COMMENT ON COLUMN "account_products"."id" IS '상품 ID';
COMMENT ON COLUMN "account_products"."product_name" IS '상품명';
COMMENT ON COLUMN "account_products"."interest_rate" IS '연 금리 (%)';
COMMENT ON COLUMN "account_products"."description" IS '상품 설명';

CREATE TABLE IF NOT EXISTS "users" (
	-- 회원 ID
	"id" UUID,
	-- 로그인 아이디
	"login_id" VARCHAR(30) NOT NULL UNIQUE,
	-- 이메일
	"email" VARCHAR(255) NOT NULL UNIQUE,
	-- 이름
	"user_name" VARCHAR(50) NOT NULL,
	-- 생년월일
	"birth" DATE,
	-- 휴대폰 번호
	"phone_num" VARCHAR(20) NOT NULL UNIQUE,
	-- 비밀번호 (해시)
	"password_hash" VARCHAR(255) NOT NULL,
	-- 간편비밀번호 PIN 6자리 (해시)
	"pin" VARCHAR(255) NOT NULL,
	-- 로그인 실패 횟수
	"login_fail_count" INT NOT NULL DEFAULT '0',
	-- PIN 실패 횟수
	"pin_fail_count" INT NOT NULL DEFAULT '0',
	-- 회원 상태: ACTIVE 정상 / LOCKED 잠금 / WITHDRAWN 탈퇴
	"status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
	-- 가입일시
	"created_at" TIMESTAMPTZ NOT NULL,
	-- 탈퇴일시
	"withdrawn_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS '회원';
COMMENT ON COLUMN "users"."id" IS '회원 ID';
COMMENT ON COLUMN "users"."login_id" IS '로그인 아이디';
COMMENT ON COLUMN "users"."email" IS '이메일';
COMMENT ON COLUMN "users"."user_name" IS '이름';
COMMENT ON COLUMN "users"."birth" IS '생년월일';
COMMENT ON COLUMN "users"."phone_num" IS '휴대폰 번호';
COMMENT ON COLUMN "users"."password_hash" IS '비밀번호 (해시)';
COMMENT ON COLUMN "users"."pin" IS '간편비밀번호 PIN 6자리 (해시)';
COMMENT ON COLUMN "users"."login_fail_count" IS '로그인 실패 횟수';
COMMENT ON COLUMN "users"."pin_fail_count" IS 'PIN 실패 횟수';
COMMENT ON COLUMN "users"."status" IS '회원 상태: ACTIVE 정상 / LOCKED 잠금 / WITHDRAWN 탈퇴';
COMMENT ON COLUMN "users"."created_at" IS '가입일시';
COMMENT ON COLUMN "users"."withdrawn_at" IS '탈퇴일시';

CREATE TABLE IF NOT EXISTS "favorite_recipients" (
	-- 즐겨찾기 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 회원 ID
	"user_id" UUID NOT NULL,
	-- 받는 계좌번호
	"account_num" VARCHAR(13) NOT NULL,
	-- 예금주
	"holder_name" VARCHAR(50) NOT NULL,
	-- 별칭
	"alias" VARCHAR(50),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "favorite_recipients" IS '자주 쓰는 받는 계좌';
COMMENT ON COLUMN "favorite_recipients"."id" IS '즐겨찾기 ID';
COMMENT ON COLUMN "favorite_recipients"."user_id" IS '회원 ID';
COMMENT ON COLUMN "favorite_recipients"."account_num" IS '받는 계좌번호';
COMMENT ON COLUMN "favorite_recipients"."holder_name" IS '예금주';
COMMENT ON COLUMN "favorite_recipients"."alias" IS '별칭';

CREATE TABLE IF NOT EXISTS "auto_transfers" (
	-- 자동이체 ID
	"id" UUID,
	-- 출금 계좌 ID
	"from_account_id" UUID NOT NULL,
	-- 입금 계좌 ID
	"to_account_id" UUID NOT NULL,
	-- 이체 금액 (원)
	"amount" BIGINT NOT NULL,
	-- 메모
	"memo" VARCHAR(100),
	-- 주기: WEEKLY 매주 / MONTHLY 매월
	"cycle" VARCHAR(10) NOT NULL,
	-- 실행일: 매주 0(월)~6(일) / 매월 1~31
	"run_day" INT NOT NULL,
	-- 시작일
	"start_date" DATE NOT NULL,
	-- 종료일
	"end_date" DATE,
	-- 다음 실행일
	"next_run_date" DATE NOT NULL,
	-- 상태: ACTIVE 사용중 / ENDED 종료 / CANCELED 해지
	"status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
	-- 등록일시
	"created_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "auto_transfers" IS '자동이체';
COMMENT ON COLUMN "auto_transfers"."id" IS '자동이체 ID';
COMMENT ON COLUMN "auto_transfers"."from_account_id" IS '출금 계좌 ID';
COMMENT ON COLUMN "auto_transfers"."to_account_id" IS '입금 계좌 ID';
COMMENT ON COLUMN "auto_transfers"."amount" IS '이체 금액 (원)';
COMMENT ON COLUMN "auto_transfers"."memo" IS '메모';
COMMENT ON COLUMN "auto_transfers"."cycle" IS '주기: WEEKLY 매주 / MONTHLY 매월';
COMMENT ON COLUMN "auto_transfers"."run_day" IS '실행일: 매주 0(월)~6(일) / 매월 1~31';
COMMENT ON COLUMN "auto_transfers"."start_date" IS '시작일';
COMMENT ON COLUMN "auto_transfers"."end_date" IS '종료일';
COMMENT ON COLUMN "auto_transfers"."next_run_date" IS '다음 실행일';
COMMENT ON COLUMN "auto_transfers"."status" IS '상태: ACTIVE 사용중 / ENDED 종료 / CANCELED 해지';
COMMENT ON COLUMN "auto_transfers"."created_at" IS '등록일시';

CREATE INDEX "idx_auto_transfers_next_run"
ON "auto_transfers" ("next_run_date");

CREATE TABLE IF NOT EXISTS "statement_requests" (
	-- 다운로드 신청 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 계좌 ID
	"account_id" UUID NOT NULL,
	-- 조회 시작일
	"from_date" DATE NOT NULL,
	-- 조회 종료일
	"to_date" DATE NOT NULL,
	-- 받을 이메일
	"email" VARCHAR(255) NOT NULL,
	-- 처리 상태: REQUESTED 접수 / SENT 발송완료 / FAILED 실패
	"status" VARCHAR(20) NOT NULL DEFAULT 'REQUESTED',
	-- 신청일시
	"created_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "statement_requests" IS '거래내역 다운로드 신청';
COMMENT ON COLUMN "statement_requests"."id" IS '다운로드 신청 ID';
COMMENT ON COLUMN "statement_requests"."account_id" IS '계좌 ID';
COMMENT ON COLUMN "statement_requests"."from_date" IS '조회 시작일';
COMMENT ON COLUMN "statement_requests"."to_date" IS '조회 종료일';
COMMENT ON COLUMN "statement_requests"."email" IS '받을 이메일';
COMMENT ON COLUMN "statement_requests"."status" IS '처리 상태: REQUESTED 접수 / SENT 발송완료 / FAILED 실패';
COMMENT ON COLUMN "statement_requests"."created_at" IS '신청일시';

CREATE TABLE IF NOT EXISTS "notifications" (
	-- 알림 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 회원 ID
	"user_id" UUID NOT NULL,
	-- 알림 종류: CARD_PAYMENT 카드결제 / SUSPICIOUS_LOGIN 이상접속 / AUTO_TRANSFER_FAIL 자동이체 실패
	"type" VARCHAR(30) NOT NULL,
	-- 알림 내용
	"message" VARCHAR(500) NOT NULL,
	-- 읽은 일시
	"read_at" TIMESTAMPTZ,
	-- 알림 생성일시
	"created_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "notifications" IS '알림';
COMMENT ON COLUMN "notifications"."id" IS '알림 ID';
COMMENT ON COLUMN "notifications"."user_id" IS '회원 ID';
COMMENT ON COLUMN "notifications"."type" IS '알림 종류: CARD_PAYMENT 카드결제 / SUSPICIOUS_LOGIN 이상접속 / AUTO_TRANSFER_FAIL 자동이체 실패';
COMMENT ON COLUMN "notifications"."message" IS '알림 내용';
COMMENT ON COLUMN "notifications"."read_at" IS '읽은 일시';
COMMENT ON COLUMN "notifications"."created_at" IS '알림 생성일시';

CREATE TABLE IF NOT EXISTS "login_histories" (
	-- 접속기록 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 회원 ID
	"user_id" UUID NOT NULL,
	-- 접속 IP
	"ip" VARCHAR(45),
	-- 접속 기기·브라우저
	"user_agent" VARCHAR(500),
	-- 로그인 성공 여부
	"success" BOOLEAN NOT NULL,
	-- 접속일시
	"created_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "login_histories" IS '로그인 접속 기록';
COMMENT ON COLUMN "login_histories"."id" IS '접속기록 ID';
COMMENT ON COLUMN "login_histories"."user_id" IS '회원 ID';
COMMENT ON COLUMN "login_histories"."ip" IS '접속 IP';
COMMENT ON COLUMN "login_histories"."user_agent" IS '접속 기기·브라우저';
COMMENT ON COLUMN "login_histories"."success" IS '로그인 성공 여부';
COMMENT ON COLUMN "login_histories"."created_at" IS '접속일시';

CREATE TABLE IF NOT EXISTS "verification_codes" (
	-- 인증번호 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 받는 이메일
	"email" VARCHAR(255) NOT NULL,
	-- 인증 목적: SIGNUP 가입 / UNLOCK_ACCOUNT 거래중지 해제 / RESET_PW 비밀번호 재설정
	"purpose" VARCHAR(20) NOT NULL,
	-- 인증번호 (해시)
	"code_hash" VARCHAR(255) NOT NULL,
	-- 만료일시
	"expires_at" TIMESTAMPTZ NOT NULL,
	-- 시도 횟수
	"attempts" INT NOT NULL DEFAULT '0',
	-- 인증 완료일시
	"verified_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "verification_codes" IS '본인확인 인증번호';
COMMENT ON COLUMN "verification_codes"."id" IS '인증번호 ID';
COMMENT ON COLUMN "verification_codes"."email" IS '받는 이메일';
COMMENT ON COLUMN "verification_codes"."purpose" IS '인증 목적: SIGNUP 가입 / UNLOCK_ACCOUNT 거래중지 해제 / RESET_PW 비밀번호 재설정';
COMMENT ON COLUMN "verification_codes"."code_hash" IS '인증번호 (해시)';
COMMENT ON COLUMN "verification_codes"."expires_at" IS '만료일시';
COMMENT ON COLUMN "verification_codes"."attempts" IS '시도 횟수';
COMMENT ON COLUMN "verification_codes"."verified_at" IS '인증 완료일시';

CREATE TABLE IF NOT EXISTS "term_agreements" (
	-- 약관동의 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 회원 ID
	"user_id" UUID NOT NULL,
	-- 약관 ID
	"term_id" BIGINT NOT NULL,
	-- 동의 여부
	"agreed" BOOLEAN NOT NULL,
	-- 동의일시
	"agreed_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "term_agreements" IS '약관 동의 내역';
COMMENT ON COLUMN "term_agreements"."id" IS '약관동의 ID';
COMMENT ON COLUMN "term_agreements"."user_id" IS '회원 ID';
COMMENT ON COLUMN "term_agreements"."term_id" IS '약관 ID';
COMMENT ON COLUMN "term_agreements"."agreed" IS '동의 여부';
COMMENT ON COLUMN "term_agreements"."agreed_at" IS '동의일시';

CREATE TABLE IF NOT EXISTS "terms" (
	-- 약관 ID
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 약관 제목
	"title" VARCHAR(200) NOT NULL,
	-- 약관 내용
	"content" TEXT NOT NULL,
	-- 약관 버전
	"version" VARCHAR(20) NOT NULL,
	-- 필수 여부
	"required" BOOLEAN NOT NULL,
	-- 약관 구분: SIGNUP 회원가입 / ACCOUNT_OPEN 계좌개설
	"category" VARCHAR(20) NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "terms" IS '약관';
COMMENT ON COLUMN "terms"."id" IS '약관 ID';
COMMENT ON COLUMN "terms"."title" IS '약관 제목';
COMMENT ON COLUMN "terms"."content" IS '약관 내용';
COMMENT ON COLUMN "terms"."version" IS '약관 버전';
COMMENT ON COLUMN "terms"."required" IS '필수 여부';
COMMENT ON COLUMN "terms"."category" IS '약관 구분: SIGNUP 회원가입 / ACCOUNT_OPEN 계좌개설';

